/** La generación con IA de EGD no está en OpenNite: avisa en lugar de abrir el asistente. */
function egdStudioNoAI({ title = 'IA' } = {}) {
  const host = document.getElementById('toast-host');
  if (!host) return;
  const d = document.createElement('div');
  d.className = 'toast';
  d.textContent = `${title}: la generación con IA de EGD no está disponible en OpenNite.`;
  host.appendChild(d);
  setTimeout(() => d.remove(), 3200);
}

